import { NextRequest, NextResponse } from "next/server";
import play from "play-dl";

export async function GET(request: NextRequest) {
  try {
    const searchParams = request.nextUrl.searchParams;
    const title = searchParams.get("title");
    const artist = searchParams.get("artist");
    const isPlayRequest = searchParams.get("play") === "true";

    if (!title || !artist) {
      return NextResponse.json(
        { error: "Missing required parameters: 'title' and 'artist'" },
        { status: 400 }
      );
    }

    const searchQuery = `${artist} ${title}`;

    try {
      // Инициализируем бесплатный Client ID для SoundCloud перед поиском
      const clientId = await play.getFreeClientID();
      await play.setToken({
        soundcloud: {
          client_id: clientId
        }
      });

      // 1. Ищем трек в SoundCloud
      const searchResults = await play.search(searchQuery, {
        limit: 1,
        source: { soundcloud: "tracks" }
      });

      if (!searchResults || searchResults.length === 0) {
        return NextResponse.json(
          { error: "No audio found on SoundCloud" },
          { status: 404 }
        );
      }

      const track = searchResults[0];

      // 2. Если запрос пришел от плеера (play=true), отдаем сам аудиопоток
      if (isPlayRequest) {
        const streamData = await play.stream(track.url);
        
        return new NextResponse(streamData.stream as any, {
          status: 200,
          headers: {
            "Content-Type": "audio/mpeg",
            "Transfer-Encoding": "chunked",
          },
        });
      }

      // 3. Если запрос от фронтенда, отдаем JSON со ссылкой на этот же роут
      return NextResponse.json(
        {
          url: `/api/audio?title=${encodeURIComponent(title)}&artist=${encodeURIComponent(artist)}&play=true`,
          title: track.name || title,
        },
        { status: 200 }
      );
      
    } catch (scError) {
      console.error("play-dl SoundCloud error:", scError);
      return NextResponse.json(
        { error: "Failed to retrieve audio", details: scError instanceof Error ? scError.message : "Unknown error" },
        { status: 500 }
      );
    }
  } catch (error) {
    console.error("Audio API error:", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 }
    );
  }
}